import{c as t,J as a,h as o,k as n}from"./chunks/framework.WgZQdPFo.js";const h=JSON.parse('{"title":"Accounts & Wallets","description":"Tracking cash, debit cards, deposits, multi-currency accounts, and stablecoins in the My Capital workspace.","frontmatter":{"title":"Accounts & Wallets","description":"Tracking cash, debit cards, deposits, multi-currency accounts, and stablecoins in the My Capital workspace.","order":17},"headers":[],"relativePath":"docs/spaces/moy-kapital/accounts.md","filePath":"docs/spaces/moy-kapital/accounts.md"}'),i={name:"docs/spaces/moy-kapital/accounts.md"};function r(s,e,c,l,d,u){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="accounts-wallets" tabindex="-1">Accounts &amp; Wallets <a class="header-anchor" href="#accounts-wallets" aria-label="Permalink to &quot;Accounts &amp; Wallets&quot;">​</a></h1><p>The <strong>Accounts &amp; Wallets</strong> tab serves as the primary liquid liquidity center in the My Capital workspace. Here you record all funds not tied directly to active production cycles: cash reserves, debit cards, high-yield savings, foreign currencies, and transactional stablecoins (USDT, USDC).</p><hr><h2 id="two-creation-modes-single-account-vs-group" tabindex="-1">Two Creation Modes: Single Account vs. Group <a class="header-anchor" href="#two-creation-modes-single-account-vs-group" aria-label="Permalink to &quot;Two Creation Modes: Single Account vs. Group&quot;">​</a></h2><p>Clicking the <strong>&quot;Add&quot;</strong> button in the upper-right corner opens a modal dialog with a mode switcher:</p><ol><li><strong>Single Account:</strong> a concise form for standalone accounts (e.g., an individual credit card, a physical cash envelope, or an emergency deposit).</li><li><strong>Group / Bank / Vault:</strong> a multi-currency container enabling you to register an entire banking institution with all its accounts (checking, savings, foreign currency) in one cohesive pass.</li></ol><div class="tip custom-block"><p class="custom-block-title">Adding Multiple Currencies Quickly</p><p>In Group mode, use the <strong>&quot;Add another currency / account to group&quot;</strong> button to dynamically append multiple accounts with individual balances, currencies, and notes under the same bank.</p></div><hr><h2 id="multi-currency-handling-and-field-layout" tabindex="-1">Multi-Currency Handling and Field Layout <a class="header-anchor" href="#multi-currency-handling-and-field-layout" aria-label="Permalink to &quot;Multi-Currency Handling and Field Layout&quot;">​</a></h2><p>Each account specifies:</p><ul><li><strong>Account Name:</strong> descriptive title (&quot;Main Debit Card&quot;, &quot;High-Yield Savings&quot;, &quot;Cash Vault&quot;).</li><li><strong>Account Type:</strong> functional tag (&quot;Card&quot;, &quot;Deposit&quot;, &quot;Cash&quot;, &quot;E-Wallet&quot;, &quot;Crypto&quot;). Defaults to <em>&quot;Uncategorized&quot;</em>. Types can be customized on the fly via the edit pencil icon.</li><li><strong>Currency &amp; Exchange Rate:</strong> select from standard world currencies or enter custom symbols. If the account currency differs from your base capital currency, the exchange rate field appears automatically.</li><li><strong>Balance &amp; Rate in One Row:</strong> the balance and exchange rate fields are compactly placed side-by-side in a single row for ergonomic data entry.</li></ul><div class="info custom-block"><p class="custom-block-title">Currency Rate Rules</p><p>For base currency accounts, the rate is permanently $1.00$ and hidden. For foreign currencies, enter the conversion multiplier to the base unit (e.g., $1\\text{ USD} = 93.50\\text{ RUB}$). Updating rates in the centralized rates dialog recalculates all converted values automatically.</p></div><hr><h2 id="group-cards-and-consolidated-balances" tabindex="-1">Group Cards and Consolidated Balances <a class="header-anchor" href="#group-cards-and-consolidated-balances" aria-label="Permalink to &quot;Group Cards and Consolidated Balances&quot;">​</a></h2><p>Accounts sharing the same group name are grouped into clear, unified cards:</p><ul><li><strong>Group Header:</strong> bank or institution name, category badge (&quot;Banks &amp; Deposits&quot;, &quot;Crypto Wallets&quot;), and item count indicator.</li><li><strong>Consolidated Total:</strong> the combined balance of all accounts in the group, automatically converted to the base currency at current exchange rates.</li><li><strong>Account Rows:</strong> line items displaying native currency balance, base currency equivalent, online banking links, and private notes.</li></ul><h3 id="header-quick-actions" tabindex="-1">Header Quick Actions <a class="header-anchor" href="#header-quick-actions" aria-label="Permalink to &quot;Header Quick Actions&quot;">​</a></h3><p>The upper-right corner of each group card contains compact action buttons:</p><ul><li><strong>&quot;+&quot; Button (Quick Add):</strong> instantly opens the account creation dialog with this group name pre-filled.</li><li><strong>Up / Down Arrows (Reordering):</strong> manually move the group card up or down in the overall list. Inactive boundary arrows are styled with a subtle inactive tone.</li><li><strong>Pencil Button (Manage Group):</strong> opens a dedicated modal dialog for renaming the group with cascading updates to all child accounts, changing group category, and reordering positions.</li></ul><hr><h2 id="view-modes-grid-tiles-vs-compact-stripes" tabindex="-1">View Modes: Grid Tiles vs. Compact Stripes <a class="header-anchor" href="#view-modes-grid-tiles-vs-compact-stripes" aria-label="Permalink to &quot;View Modes: Grid Tiles vs. Compact Stripes&quot;">​</a></h2><p>The toolbar includes a view density toggle:</p><ul><li><strong>Grid Tiles (Columns):</strong> spacious responsive card grid ideal for desktop monitors, grouping cards by category with natural card heights.</li><li><strong>Compact Stripes:</strong> dense vertical rows for rapid auditing, with collapsible account lists.</li></ul><div class="tip custom-block"><p class="custom-block-title">Global Collapse / Expand</p><p>The <strong>&quot;↕&quot;</strong> button on the toolbar expands or collapses all group cards simultaneously with a single click.</p></div><hr><h2 id="archiving-and-safe-deletion" tabindex="-1">Archiving and Safe Deletion <a class="header-anchor" href="#archiving-and-safe-deletion" aria-label="Permalink to &quot;Archiving and Safe Deletion&quot;">​</a></h2><p>When an account is closed at a bank, you do not need to delete the history—simply move it to the archive:</p><ol><li>Open the account edit dialog or click the card action menu.</li><li>Select <strong>&quot;Archive&quot;</strong>. The account disappears from active views and ceases to affect liquid totals.</li><li>Groups automatically hide from the active screen when all member accounts are archived.</li></ol><p>To review archived records, toggle the <strong>&quot;Archive&quot;</strong> button on the toolbar. From there, accounts can be restored or permanently removed (with soft delete safeguards <code>is_deleted = 1</code>).</p>',29)])])}const g=t(i,[["render",r]]);export{h as __pageData,g as default};
